fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    let mut best: Option<Vec<char>> = None;
    let mut best_len: usize = 0;

    for s in strings.into_iter() {
        let len = s.len();
        // If we haven't picked any sequence yet, or this one is strictly longer, update.
        if best.is_none() || len > best_len {
            best_len = len;
            best = Some(s);
        }
    }

    best
}

